// The isolate hands back only JSON-serializable primitives: return the result as a JSON string.
JSON.stringify((function () {
    const parse = (x) => (typeof x === 'string' && x ? JSON.parse(x) : (x || null));
    const item = parse($data.item) || {};
    const changes = parse($data.changes) || {};
    const node = parse($data.content) || {};
    const field = changes.field_value || {};
    const status = String(field.to || '');
    const from = String(field.from || '');
    if (!status) return { ok: false, reason: 'no target status in the change' };
    const errors = parse($data.errors) || [];
    if (!node.__typename) {
        // GitHub answered without the node: usually a permission problem (the organization's
        // OAuth app policy, a private repository the account cannot read) — say so.
        const why = errors.length ? 'GitHub: ' + String(errors[0].message || errors[0].type || '').slice(0, 300) : 'content node not returned';
        return { ok: false, reason: why, status, from };
    }
    if (node.__typename === 'DraftIssue') {
        return { ok: false, reason: 'draft issue: nothing to resolve', status, from };
    }
    const repoOf = (n) => (n && n.repository && n.repository.nameWithOwner) || '';
    const labels = ((node.labels || {}).nodes || []).map((l) => l.name);
    const connectors = labels.filter((l) => l.indexOf('appmixer:') === 0).map((l) => l.slice('appmixer:'.length));
    let issue = null;
    let pr = null;
    if (node.__typename === 'Issue') {
        issue = { number: node.number, url: node.url, repo: repoOf(node), title: node.title, state: node.state };
        // The PR that closes the issue: an open one first, else the newest
        const linked = ((node.closedByPullRequestsReferences || {}).nodes || []);
        // The PR to test: the first open, non-draft one of the connectors repo; then any open one;
        // then the newest closed. The Testing runner re-checks there is exactly one candidate.
        const open = linked.filter((p) => p.state === 'OPEN');
        const inConnectors = (p) => repoOf(p) === 'Appmixer-ai/appmixer-connectors';
        const chosen = open.filter((p) => inConnectors(p) && !p.isDraft)[0] || open.filter(inConnectors)[0] || open[0] || linked[linked.length - 1];
        if (chosen) pr = { number: chosen.number, url: chosen.url, repo: repoOf(chosen), state: chosen.state, isDraft: !!chosen.isDraft, branch: chosen.headRefName || '' };
    } else if (node.__typename === 'PullRequest') {
        pr = { number: node.number, url: node.url, repo: repoOf(node), title: node.title, state: node.state, isDraft: !!node.isDraft, branch: node.headRefName || '' };
    } else {
        return { ok: false, reason: 'unsupported content type ' + node.__typename, status, from };
    }
    const target = issue || pr;
    return {
        ok: true,
        status,
        from,
        // Deterministic: a webhook redelivery of the same change produces the same id
        runId: [item.node_id, status, item.updated_at].join(':'),
        item: { nodeId: item.node_id, projectNodeId: item.project_node_id, contentType: item.content_type },
        issue,
        pr,
        connector: connectors.join(','),
        branch: pr ? pr.branch : '',
        target: issue ? 'issue' : 'pr',
        targetRepo: target.repo,
        targetNumber: target.number,
        commentsUrl: '/repos/' + target.repo + '/issues/' + target.number + '/comments?per_page=100',
        organization: String($data.organization || ''),
        projectNodeId: String(item.project_node_id || ''),
        statusFieldId: String(field.field_node_id || ''),
        target: target.repo + '#' + target.number,
        prUrl: pr ? String(pr.url || '') : '',
        // OpenClaw hook of the stage this status starts ('' = the status only records the move)
        hook: ({ 'Testing': 'vero-testing', 'Doc&Verification': 'maya-docs' })[status] || '',
        // Appmixer integration of the stage this status starts (its webhook URL is set in the wizard)
        flowStage: status === 'Pre-release' ? 'Pre-release' : '',
        by: String($data.sender || '')
    };
})())

// Finds the pipeline comment on the item, drops a run already recorded, otherwise rewrites the
// comment with the new status move. The machine-readable state sits in <!-- pipeline: {...} -->.
JSON.stringify((function () {
    const parse = (x) => (typeof x === 'string' && x ? JSON.parse(x) : (x || null));

    const RENDER = function (state, lastRun) {
        const icon = { passed: '✅', failed: '❌', blocked: '⏸️', running: '⏳' };
        const when = (at) => String(at || '').slice(0, 16).replace('T', ' ') + ' UTC';
        const short = (t, n) => { const s = String(t || '').replace(/\s+/g, ' ').trim(); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
        const html = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
        const row = (r) => '- ' + when(r.at) + ' · ' + (r.from || '—') + ' → **' + r.to + '** (' + r.by + ')';
        const stages = Object.keys(state.stages || {}).map((name) => {
            const s = state.stages[name];
            const detailed = s.report && s.result !== 'passed' && s.result !== 'running';
            const head = (icon[s.result] || '') + ' ' + name + (detailed ? '' : ' · ' + short(s.summary, 120)) + ' · ' + when(s.at) + (Number(s.cost) >= 0.005 ? ' · $' + Number(s.cost).toFixed(2) : '');
            // The report only for a stage that did not pass: what is wrong, with its links
            return '- ' + head + (detailed ? '\n\n' + s.report.split('\n').map((l) => (l ? '  ' + l : l)).join('\n') + '\n' : '');
        });
        // "--" never reaches the HTML comment, so a report cannot close the state block early
        const json = JSON.stringify(state).replace(/--/g, '\\u002d\\u002d');
        const now = state.now || {};
        const last = state.runs[state.runs.length - 1];
        return [
            '🤖 **Pipeline** · ' + (state.connector || '—') + (state.pr ? ' · ' + state.pr : '')
                + (state.cost && Number(state.cost.total) >= 0.005 ? ' · $' + Number(state.cost.total).toFixed(2) + ' so far' : ''),
            '',
            stages.join('\n'),
            '',
            last ? 'Last move: ' + row(last).slice(2) + ' · ' + state.runs.length + ' moves in total' : '',
            '',
            '**' + (now.status || (last && last.to) || '—') + (now.problem ? ':** ' + now.problem : '**'),
            now.next ? '\n**Next:** ' + now.next : '',
            '',
            '<!-- pipeline: ' + json + ' -->'
        ].join('\n');
    };
    const READ_STATE = function (comments) {
        const existing = (comments || []).filter((c) => typeof c.body === 'string' && c.body.indexOf('<!-- pipeline: ') >= 0)[0];
        let state = { runs: [], stages: {} };
        if (existing) {
            const m = existing.body.match(/<!-- pipeline: (\{[\s\S]*?\}) -->/);
            if (m) { try { state = JSON.parse(m[1]); } catch (e) { state = { runs: [], stages: {} }; } }
        }
        if (!Array.isArray(state.runs)) state.runs = [];
        if (!state.stages || typeof state.stages !== 'object') state.stages = {};
        return { existing, state };
    };

    const event = parse($data.event) || {};
    const { existing, state } = READ_STATE(parse($data.comments) || []);
    if (state.runs.some((r) => r.id === event.runId)) {
        return { duplicate: true, runId: event.runId };
    }
    state.runs.push({ id: event.runId, at: new Date().toISOString(), from: event.from, to: event.status, by: event.by });
    state.runs = state.runs.slice(-30);
    state.connector = event.connector || state.connector || '';
    state.pr = event.prUrl || state.pr || '';
    state.organization = event.organization || state.organization || '';
    const STARTED = { 'Testing': 'Started: E2E of the changed connectors on dev-automated-00001.', 'Doc&Verification': 'Started: maya checks the app registration guide of the changed connectors.', 'Pre-release': 'Started: the pre-release checklist and a design review by Claude.' };
    if ((event.hook || event.flowStage) && event.prUrl && STARTED[event.status]) {
        state.stages[event.status] = { result: 'running', summary: STARTED[event.status], at: new Date().toISOString() };
    }
    // The sentence of what follows after a move; a stage result that moved the card wrote its own
    // Where the card goes after the review: Pre-release once the docs are done (passed or a docs PR open)
    const afterReview = function (st) {
        const docs = st.stages && st.stages['Doc&Verification'];
        const done = docs && (docs.result === 'passed' || /appmixer-docs-gitbook\/pull\/\d+/.test(String(docs.summary || '') + ' ' + String(docs.report || '')));
        return 'A person reviews the PR, then moves the card to ' + (done ? 'Pre-release (the docs are done).' : 'Doc&Verification.');
    };
    const NEXT = {
        'Testing': 'Testing runs the E2E flows; the result appears here.',
        'Doc&Verification': 'maya checks the app registration guide; the result appears here.',
        'Pre-release': 'The pre-release checklist and the design review run; the result appears here.',
        'Review': afterReview(state),
        'In Progress': 'The PR is being worked on; move the card to Testing when it is ready.',
        'Done': 'Merged; it ships with the next release.'
    };
    if (!state.now || state.now.status !== event.status) {
        state.now = { status: event.status, problem: '', next: NEXT[event.status] || '', at: new Date().toISOString() };
    }
    const body = RENDER(state, event.runId);
    return existing
        ? { duplicate: false, method: 'PATCH', url: '/repos/' + event.targetRepo + '/issues/comments/' + existing.id, body: JSON.stringify({ body }) }
        : { duplicate: false, method: 'POST', url: '/repos/' + event.targetRepo + '/issues/' + event.targetNumber + '/comments', body: JSON.stringify({ body }) };
})())
